#!/usr/bin/env python3
"""Make the fixed sp-code-v1 test vector with Python's `cryptography` library.

This is an independent implementation of the sealing side (what the website
does with WebCrypto), so the Go test that opens the vector checks both sides
agree on P-256 ECDH, HKDF-SHA256 and AES-256-GCM exactly as specified.

Every key and the code are made up for this test. Nothing here is a real
secret. The private keys come from fixed labels so the output never changes.

Usage: python3 sealed_code_vector.py [out.json]
(needs: pip install cryptography)
"""

import base64
import hashlib
import json
import sys

from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.kdf.hkdf import HKDF

SCHEME = "sp-code-v1"
SERIAL = "01P00A000000001"  # made up
CODE = "Vx7Kq2Lm"  # made up
P256_N = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551


def b64u(b: bytes) -> str:
    return base64.urlsafe_b64encode(b).rstrip(b"=").decode()


def fixed_scalar(label: str) -> int:
    d = int.from_bytes(hashlib.sha256(label.encode()).digest(), "big") % P256_N
    assert d != 0
    return d


def uncompressed(pub: ec.EllipticCurvePublicKey) -> bytes:
    return pub.public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)


def main() -> None:
    link_priv = ec.derive_private_key(fixed_scalar("sp-code-v1 test vector: link key"), ec.SECP256R1())
    eph_priv = ec.derive_private_key(fixed_scalar("sp-code-v1 test vector: ephemeral key"), ec.SECP256R1())
    nonce = hashlib.sha256(b"sp-code-v1 test vector: nonce").digest()[:12]

    link_pub = uncompressed(link_priv.public_key())
    epk = uncompressed(eph_priv.public_key())
    key_id = hashlib.sha256(link_pub).hexdigest()[:16]

    shared = eph_priv.exchange(ec.ECDH(), link_priv.public_key())
    aes_key = HKDF(algorithm=hashes.SHA256(), length=32, salt=epk, info=SCHEME.encode()).derive(shared)
    aad = f"{SCHEME}|{SERIAL}|{key_id}".encode()
    ciphertext = AESGCM(aes_key).encrypt(nonce, CODE.encode(), aad)
    assert len(epk) == 65 and len(nonce) == 12 and len(ciphertext) == 24

    # The link side opens it, as a self check.
    shared2 = link_priv.exchange(ec.ECDH(), ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), epk))
    assert shared2 == shared

    d = link_priv.private_numbers().private_value.to_bytes(32, "big")
    nums = link_priv.public_key().public_numbers()
    jwk = {
        "kty": "EC",
        "crv": "P-256",
        "x": b64u(nums.x.to_bytes(32, "big")),
        "y": b64u(nums.y.to_bytes(32, "big")),
        "d": b64u(d),
    }
    pkcs8 = link_priv.private_bytes(
        serialization.Encoding.DER, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()
    )

    vector = {
        "comment": "sp-code-v1 fixed test vector. Made-up keys and code, not secrets. Generated by sealed_code_vector.py (Python cryptography).",
        "scheme": SCHEME,
        "link_private_key_hex": d.hex(),
        "link_private_pkcs8_b64": base64.b64encode(pkcs8).decode(),
        "link_private_jwk": json.dumps(jwk, separators=(",", ":")),
        "link_public_key": b64u(link_pub),
        "key_id": key_id,
        "serial": SERIAL,
        "code": CODE,
        "aad": aad.decode(),
        "eph_private_key_hex": eph_priv.private_numbers().private_value.to_bytes(32, "big").hex(),
        "epk": b64u(epk),
        "nonce": b64u(nonce),
        "ciphertext": b64u(ciphertext),
        "shared_secret_hex": shared.hex(),
        "aes_key_hex": aes_key.hex(),
        "envelope": {
            "scheme": SCHEME,
            "key_id": key_id,
            "epk": b64u(epk),
            "nonce": b64u(nonce),
            "ciphertext": b64u(ciphertext),
        },
    }
    out = json.dumps(vector, indent=2) + "\n"
    if len(sys.argv) > 1:
        with open(sys.argv[1], "w") as f:
            f.write(out)
    else:
        sys.stdout.write(out)


if __name__ == "__main__":
    main()
